    pub fn set_hidden(&self, key: &str, value: Value) {
        self.set_prop(PropKey::from_str(key), value, WC)
    }
    pub fn set_accessor(&self, key: PropKey, get: Option<Obj>, set: Option<Obj>, flags: u8) {
