const log = [];
const opts = new Proxy({}, { get(t, k) { log.push(String(k)); return undefined; }, has(t, k) { log.push('has:' + String(k)); return false; } });
new Intl.Collator('en', opts);
console.log('read order: ' + log.join(','));
const log2 = [];
const o2 = {};
for (const k of ['usage', 'localeMatcher', 'collation', 'numeric', 'caseFirst', 'sensitivity', 'ignorePunctuation']) {
  Object.defineProperty(o2, k, { get() { log2.push(k); return undefined; } });
}
new Intl.Collator('en', o2);
console.log('read order2: ' + log2.join(','));
// tostring conversions
const tl = [];
const mk = (name, val) => ({ toString() { tl.push(name); return val; } });
try { new Intl.Collator('en', {usage: mk('usage', 'sort'), localeMatcher: mk('lm', 'lookup'), collation: mk('co', 'default'), numeric: mk('num', 'x'), caseFirst: mk('cf', 'upper'), sensitivity: mk('s', 'base'), ignorePunctuation: mk('ip', 'x')}); } catch (e) { console.log('ERR', e.message); }
console.log('tostring order: ' + tl.join(','));
const langs = ['en','ar','de','es','fr','gv','hi','it','ja','ko','ln','nl','pl','pt','ru','si','sl','sr','sv','th','zh','zh-TW','zh-Hant'];
const cols = ['big5han','compat','dict','emoji','eor','gb2312','phonebk','phonetic','pinyin','reformed','searchjl','stroke','trad','unihan','zhuyin','search','standard','default','ducet'];
for (const l of langs) {
  const okOpt = [], okExt = [];
  for (const c of cols) {
    try { const r = new Intl.Collator(l, {collation: c}).resolvedOptions(); if (r.collation !== 'default') okOpt.push(c + (r.collation !== c ? '->' + r.collation : '')); } catch (e) { okOpt.push(c + ':ERR'); }
    try { const r = new Intl.Collator(l + '-u-co-' + c).resolvedOptions(); if (r.collation !== 'default' || r.locale !== l) okExt.push(c + '(' + r.locale + ',' + r.collation + ')'); } catch (e) { okExt.push(c + ':ERR ' + e.message); }
  }
  console.log(l + ' opt: ' + okOpt.join(' ') + ' | ext: ' + okExt.join(' '));
}
for (const l of langs) {
  const r = new Intl.Collator(l).resolvedOptions();
  console.log(l + ' defaults: ' + JSON.stringify(r));
}

