import unicodedata
lines = [l for l in open('/tmp/intlagent/coll/dump_bmp.txt').read().split('\n') if l]
seq = []
for l in lines:
    cp, _, rel = l.partition(' ')
    seq.append((int(cp, 16), rel))

NEW_LOWER = {0xa7dc: 0x19b, 0xa7cb: 0x264, 0x1c89: 0x1c8a, 0xa7cc: 0xa7cd, 0xa7ce: 0xa7cf, 0xa7d2: 0xa7d3, 0xa7d4: 0xa7d5, 0xa7da: 0xa7db}

def lower(ch):
    if ord(ch) in NEW_LOWER:
        return chr(NEW_LOWER[ord(ch)])
    return ch.lower()

def hyp_key(cp):
    c = chr(cp)
    d = unicodedata.normalize('NFD', c)
    prim, sec, ter = [], [], []
    for ch in d:
        if unicodedata.combining(ch) != 0 and prim:
            sec[-1].append(ord(ch))
            continue
        l = lower(ch)
        prim.append(tuple(ord(x) for x in l))
        sec.append([])
        ter.append(1 if ch != l else 0)
    return prim, sec, ter

def cmp(a, b):
    return (a > b) - (a < b)

bad = 0
